package org.sleepwell.app;
import java.util.*;import static org.sleepwell.app.TrackingDndLease.*;
/** Serialized ownership transitions, independent of Android policy APIs. */
final class TrackingDndOwner {
 interface Store{TrackingDndLease read();void save(TrackingDndLease value);void error(String message);void touched();}
 interface Port{boolean access();boolean exact();String create(String token);boolean owned(String id,String token);boolean enabled(String id,String token);void on(String id,String token);void off(String id,String token);void remove(String id,String token);void schedule(String token,long deadline);void cancel(String token,long deadline);Map<String,String> ownedRules();}
 final Store store;final Port port;final java.util.function.Supplier<String> nonce;TrackingDndOwner(Store store,Port port,java.util.function.Supplier<String> nonce){this.store=store;this.port=port;this.nonce=nonce;}
 void start(String run,boolean requested,long now,int boot,java.util.function.BooleanSupplier current){if(!current.getAsBoolean())return;TrackingDndLease old=store.read();if(old!=null&&old.run.equals(run)&&old.active)return;if(old!=null)clear(old);if(!requested||!current.getAsBoolean())return;if(!port.access())throw new IllegalStateException("Allow Do Not Disturb access before the next tracking session.");if(!port.exact())throw new IllegalStateException("Exact alarm access is required for the DND expiry safeguard.");store.touched();String token=nonce.get(),id=port.create(token);TrackingDndLease lease=new TrackingDndLease(run,token,id,Math.addExact(now,WINDOW),Math.addExact(now,HARD),boot,false);try{store.save(lease);port.schedule(token,lease.deadline);if(!current.getAsBoolean())throw new IllegalStateException("Tracking is no longer active.");port.on(id,token);store.save(lease.active());store.error("");}catch(RuntimeException failure){try{clear(lease);}catch(RuntimeException cleanup){failure.addSuppressed(cleanup);}throw failure;}}
 void stop(String run){TrackingDndLease lease=store.read();if(lease!=null&&lease.run.equals(run))clear(lease);}
 void renew(String run,long now,int boot,java.util.function.BooleanSupplier current){TrackingDndLease lease=store.read();if(lease==null||!lease.run.equals(run)||!lease.active)return;if(lease.boot!=boot||now>=lease.hard||!current.getAsBoolean()){clear(lease);return;}if(!port.access()||!port.exact())throw new IllegalStateException("DND safeguard access changed. Review Android permissions.");if(!port.owned(lease.rule,lease.token)||!port.enabled(lease.rule,lease.token)){clear(lease);store.error("The tracking DND rule was disabled or removed in Android.");return;}long until=Math.min(lease.hard,Math.addExact(now,WINDOW));if(until==lease.deadline)return;TrackingDndLease next=lease.renewed(until);port.schedule(next.token,next.deadline);try{store.save(next);}catch(RuntimeException failure){port.cancel(next.token,next.deadline);throw failure;}port.cancel(lease.token,lease.deadline);}
 void expire(String token,long expected,long now,int boot){TrackingDndLease lease=store.read();if(lease==null||!lease.token.equals(token)||lease.deadline!=expected)return;if(lease.boot!=boot||now>=lease.deadline)clear(lease);}
 void recover(java.util.function.Predicate<String> live,int boot,long now){TrackingDndLease lease=store.read();if(lease!=null&&lease.boot==boot&&lease.active&&now<lease.deadline&&live.test(lease.run))return;if(lease!=null)clear(lease);for(Map.Entry<String,String> orphan:port.ownedRules().entrySet()){if(!port.owned(orphan.getKey(),orphan.getValue()))continue;port.off(orphan.getKey(),orphan.getValue());port.remove(orphan.getKey(),orphan.getValue());}}
 void clear(TrackingDndLease lease){if(port.owned(lease.rule,lease.token)){port.off(lease.rule,lease.token);port.remove(lease.rule,lease.token);}port.cancel(lease.token,lease.deadline);TrackingDndLease saved=store.read();if(saved!=null&&saved.token.equals(lease.token)&&saved.deadline==lease.deadline)store.save(null);}
}
